/* Eski kutuyu bir kez yeni takvime çevirir: eski takvimdeki aralık gününe en yakın yeni kutu.
   Eskiden ezberde sayılan ayet ezberde kalır (en az kutu 4); sayılmayan ayet kendiliğinden ezberde olmaz (en çok kutu 3). */
function ezberGoc(x){if(!x||typeof x!=="object"||x.ezberSurum===2)return x;
  const eski=no=>{for(const k in EZ_ESKI)if(EZ_ESKI[k].includes(+no))return k.split(",").map(Number);return [1,2,4,7,14,30,60];};
  Object.entries(x.sure||{}).forEach(([no,t])=>{const D=t&&t.ezberDurum;if(!D||typeof D!=="object")return;const A=eski(no),esik=Math.min(4,A.length-1);
    Object.values(D).forEach(d=>{if(!d||typeof d.kutu!=="number"||d.kutu<0)return;const g=A[Math.min(d.kutu,A.length-1)];
      let y=0;EZ_ARALIK.forEach((v,j)=>{if(Math.abs(v-g)<Math.abs(EZ_ARALIK[y]-g))y=j;});
      d.kutu=(d.tam||d.kutu>=esik)?Math.max(y,EZ_TAM_KUTU):Math.min(y,EZ_TAM_KUTU-1);});});
  x.ezberSurum=2;return x;}
function normalize(x){
  if(x&&typeof x==="object"&&x.sure)ezberGoc(x);
  x=Object.assign({puan:0,dogru:0,ardarda:0,rekor:0,seri:0,sonGun:"",rozet:[],sure:{}},x||{});
  x.ezberSurum=2;
  if(x.yildiz||x.portre){ // eski Fatiha kaydını taşı
    x.sure["1"]=Object.assign({},x.sure["1"]||{},{yildiz:Object.assign({},x.yildiz||{},(x.sure["1"]||{}).yildiz||{}),portre:x.portre||(x.sure["1"]||{}).portre});
    delete x.yildiz;delete x.portre;
  }
  return x;
}
/* --- kişiler (profil): aynı cihazda birden çok kişi --- */
let PROF={liste:[],aktif:null};
try{const r=localStorage.getItem("bahce-profil");if(r)PROF=Object.assign(PROF,JSON.parse(r));}catch(e){}
const lsAnahtar=id=>(!id||id==="p0")?LS:LS+"-"+id;
const docAdi=id=>(!id||id==="p0")?"fatiha":"fatiha-"+id;
/* Ezberde sayılma: kutu 4 (ekranda 5. basamak), ebeveyn onayı gerekiyorsa onay alınmış olmalı; "Zorlandım" denen ayet (zayif) yeniden hatırlanana dek sayılmaz */
const ezbTam=d=>!!d&&!d.onayBekle&&!d.zayif&&(d.kutu>=EZ_TAM_KUTU||!!d.tam);
/* yaşa göre seviye: 3-6 minik, 7-9 küçük, 10-14 genç, 15+ yetişkin */
const yasSeviye=y=>y<=6?"minik":y<=9?"kucuk":y<=14?"genc":"yetiskin";
const aktifKisi=()=>PROF.liste.find(p=>p.id===PROF.aktif)||null;
function profKaydet(){try{localStorage.setItem("bahce-profil",JSON.stringify(PROF));}catch(e){}
  if(window.DBK)DBK.set({liste:PROF.liste}).catch(()=>{});}
function profYukle(id){S=normalize(null);try{const r=localStorage.getItem(lsAnahtar(id));if(r)S=normalize(JSON.parse(r));}catch(e){}}
// eski kayıt varsa ilk kişi olarak koru
try{if(!PROF.liste.length&&localStorage.getItem(LS))PROF.liste.push({id:"p0",ad:"",yas:0});}catch(e){}
if(PROF.aktif)profYukle(PROF.aktif);
const SS=n=>{const k=String(n);if(!S.sure[k])S.sure[k]={};const t=S.sure[k];
  t.yildiz=Object.assign({oku:false,kelime:false,tamamla:false,sirala:false},t.yildiz||{});
  t.portre=Object.assign({olcek:{},gecmis:[],plan:[],zit:false},t.portre||{});return t;};

const $=id=>document.getElementById(id);
const shuffle=a=>{a=a.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
const esc=t=>String(t).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const today=()=>new Date().toLocaleDateString("sv-SE");
const arNum=n=>String(n).replace(/\d/g,d=>"٠١٢٣٤٥٦٧٨٩"[d]);

let sonPuan=S.puan;
function gunlukIsle(){if(typeof sonPuan==="number"&&S.puan>sonPuan){S.gunluk=S.gunluk||{};const d=today();S.gunluk[d]=(S.gunluk[d]||0)+(S.puan-sonPuan);
  const k=Object.keys(S.gunluk).sort();while(k.length>91)delete S.gunluk[k.shift()];}sonPuan=S.puan;}
/* Buluta yazma seyrek yapılır: en çok 30 sn'de bir, sayfa gizlenince ya da kapanınca hemen; değişmeyen durum yazılmaz */
let sonYazilan="";
function bulutGonder(){clearTimeout(saveTimer);saveTimer=null;if(!docRef)return;if(navigator.onLine===false)return;   /* çevrimdışı: yazma sıraya birikmesin; "online" olunca bir kez gönderilir */
const j=JSON.stringify(S);if(j===sonYazilan)return;sonYazilan=j;docRef.set(JSON.parse(j)).catch(()=>{sonYazilan="";});}
function save(){
  gunlukIsle();
  try{localStorage.setItem(lsAnahtar(PROF.aktif),JSON.stringify(S));}catch(e){if(!save.uyari){save.uyari=1;setTimeout(()=>toast("Bu tarayıcı ilerlemeyi saklayamıyor (gizli pencere olabilir)"),500);}}
  if(docRef&&!saveTimer)saveTimer=setTimeout(bulutGonder,30000);
}
/* İki kaydı alan alan birleştirir: hiçbir cihazdaki emek kaybolmaz */
const BIR_YEREL=new Set(["seviye","hiz","tekrar","hedef","efekt","molaDk","renkModu","basaDon","tumBolum","dtAyar","eylem","eylemSor","gorev","ardarda","oturumDk","gizliT","sonSure","gunDogru"]);
function birlestir(a,b){
  if(!b||typeof b!=="object")return a;if(!a||typeof a!=="object")return b;
  /* iki taraf da yeni ezber takviminde olsun ki kutular karşılaştırılabilsin */
  if(a.sure)ezberGoc(a);if(b.sure)ezberGoc(b);
  const sonGunA=a.sonGun||"",sonGunB=b.sonGun||"";
  const bir=(x,y,ust)=>{
    if(x===undefined)return y;if(y===undefined)return x;
    if(typeof x==="number"&&typeof y==="number")return Math.max(x,y);
    if(typeof x==="boolean"&&typeof y==="boolean")return x||y;
    if(typeof x==="string"&&typeof y==="string")return /^\d{4}-\d\d-\d\d$/.test(x)&&/^\d{4}-\d\d-\d\d$/.test(y)?(x>y?x:y):x;
    if(Array.isArray(x)&&Array.isArray(y)){if(x.every(v=>typeof v!=="object")&&y.every(v=>typeof v!=="object"))return [...new Set([...x,...y])];return x.length>=y.length?x:y;}
    if(x&&y&&typeof x==="object"&&typeof y==="object"&&!Array.isArray(x)&&!Array.isArray(y)){
      if("kutu" in x&&"kutu" in y&&("sonraki" in x||"sonraki" in y)){return (y.kutu>x.kutu||(y.kutu===x.kutu&&(y.sonraki||"")>(x.sonraki||"")))?y:x;}
      const o={};new Set([...Object.keys(x),...Object.keys(y)]).forEach(k=>{o[k]=(ust&&BIR_YEREL.has(k))?(x[k]!==undefined?x[k]:y[k]):bir(x[k],y[k],false);});return o;}
    return x;};
  const o=bir(a,b,true);
  /* seri ile son gün birlikte gider: hangisi daha yeniyse onunki */
  if(sonGunB>sonGunA){o.seri=b.seri;o.sonGun=b.sonGun;}else{o.seri=a.seri;o.sonGun=a.sonGun;}
  return o;}
function toast(t){if(!/daha gerekiyor/.test(t))t=String(t).replace(/,?\s*(\d+) (ek )?puan/," · emeğin bahçeni büyüttü (+$1)");
  toast.q=toast.q||[];if(toast.q[toast.q.length-1]===t||(toast.su===t&&!toast.q.length))return;toast.q.push(t);if(toast.q.length>4)toast.q.splice(1,toast.q.length-4);if(!toast.su)toastSonraki();}
function toastSonraki(){const el=$("toast");const t=toast.q.shift();if(t===undefined){toast.su=null;el.textContent="";return;}toast.su=t;el.textContent=t;clearTimeout(toast.t);toast.t=setTimeout(toastSonraki,toast.q.length?1700:2400);}
/* Günlük seri: bir ya da iki gün kaçırılırsa ayda 2 telafi hakkıyla seri korunur (hastalık, yolculuk, bayram) */
function gun(){const t=today();if(S.sonGun===t)return;
  const fark=S.sonGun?Math.round((new Date(t+"T12:00")-new Date(S.sonGun+"T12:00"))/864e5):99;
  const ay=t.slice(0,7);if(!S.telafi||S.telafi.ay!==ay)S.telafi={ay,n:0};const kalan=2-S.telafi.n;
  if(fark===1)S.seri=S.seri+1;
  else if(fark>=2&&fark-1<=kalan&&S.seri>0){S.telafi.n+=fark-1;S.seri=S.seri+1;setTimeout(()=>toast(`Serin korundu: ${fark-1} telafi hakkı kullanıldı (bu ay ${2-S.telafi.n} hakkın kaldı)`),800);}
  else S.seri=1;
  S.sonGun=t;}
function checkBadges(){BADGES.forEach(([id,ad,f])=>{if(!S.rozet.includes(id)&&f(S)){S.rozet.push(id);toast("Yeni rozet: "+ad);efekt("yildiz");kutla(true);}});}
/* Aynı gün çok sayıda doğru cevaptan sonra puan azalır: emek puanı emekten kopmasın */
function gunlukCarpan(){const t=today();if(!S.gunDogru||S.gunDogru.g!==t)S.gunDogru={g:t,n:0};S.gunDogru.n++;const n=S.gunDogru.n;return n<=60?1:n<=120?0.5:0.2;}
function answer(ok){gun();
  if(ok){S.dogru++;S.ardarda++;S.rekor=Math.max(S.rekor,S.ardarda);S.puan+=Math.round(10*gunlukCarpan());/* art arda doğru sayılır ama ek puan vermez */
    if(S.ardarda%5===0){efekt("seri");kutla(true);}else efekt("dogru");gorevIsle("soru");hedefIsle("soru");logIsle("dogru");}else{S.ardarda=0;efekt("yanlis");}logIsle("soru");
  checkBadges();save();renderStats();}
function giveStar(k){const t=SS(CUR.no);if(!t.yildiz[k]){if(hicYildizYok()&&!S.ilkYolGec){S.ilkYolGec=true;setTimeout(()=>toast("İlk yıldızın! Bahçende ilk fidan filizlendi 🌱"),600);}t.yildiz[k]=true;toast("Yıldız kazandın: "+STAR_NAMES[k]);efekt("yildiz");kutla();
  if(yildizSay(CUR.no)===4){S.puan+=50;toast(CUR.ad+" suresini dört yıldızla bitirdin, 50 ek puan");}
  checkBadges();save();renderStats();}}
function renderStats(){
  $("sPuan").textContent=S.puan;$("sSeri").textContent=S.seri;$("sRekor").textContent=S.rekor;
  {const rk=$("sRekor").closest(".stat");if(rk)rk.hidden=S.seviye==="kucuk"||S.seviye==="minik";}
  if(CUR){$("sYildiz").textContent=yildizSay(CUR.no)+"/4";$("sYildizAd").textContent="Bu surede yıldız";}
  else{$("sYildiz").textContent=KATALOG.reduce((a,k)=>a+(k.gruplar?grupYildiz(k):yildizSay(k.no)),0);$("sYildizAd").textContent="Toplam yıldız";}
}

